PRAGMA foreign_keys = ON;

CREATE TABLE knowledge_source_assets (
  source_id TEXT PRIMARY KEY REFERENCES sources(id),
  collection_id TEXT NOT NULL,
  collection_position INTEGER NOT NULL,
  external_id TEXT NOT NULL UNIQUE,
  source_url TEXT NOT NULL,
  transcript_source TEXT NOT NULL CHECK (transcript_source IN ('automatic','manual','transcribed')),
  artifact_status TEXT NOT NULL CHECK (artifact_status IN ('complete','missing')),
  duration_seconds INTEGER NOT NULL,
  segment_count INTEGER NOT NULL,
  topic_family TEXT NOT NULL,
  method_namespace TEXT NOT NULL CHECK (method_namespace IN ('rva-specific','western','kp')),
  sensitivity TEXT NOT NULL CHECK (sensitivity IN ('standard','high-impact','restricted')),
  quality_status TEXT NOT NULL CHECK (quality_status IN ('usable','repair','retranscribe','reviewed')),
  quality_metrics_json TEXT NOT NULL,
  artifact_manifest_json TEXT NOT NULL,
  source_updated_at TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(collection_id, collection_position)
);

CREATE INDEX knowledge_assets_quality_idx ON knowledge_source_assets(quality_status, topic_family);
CREATE INDEX knowledge_assets_sensitivity_idx ON knowledge_source_assets(sensitivity);

